// N = 5 replicas. Documented: 'strongly consistent reads & writes'.
const N = 5;
const W = 2;   // ack a write after this many replicas accept
const R = 2;   // read this many replicas, return the freshest

async function writeBalance(key, value) {
  const acks = await writeToReplicas(key, value, W); // returns when W accept
  return acks >= W;
}

async function readBalance(key) {
  const replies = await readFromReplicas(key, R);    // R replicas reply
  // pick the value with the highest version among the R replies
  return replies.reduce((best, r) => (r.version > best.version ? r : best)).value;
}

async function withdraw(key, amount) {
  const bal = await readBalance(key);
  if (bal >= amount) await writeBalance(key, bal - amount); // check-then-write
}
